# Copies clang and lld of the SDK extension org.freedesktop.Sdk.Extension.llvm21 (mounted at build time through sdk-extensions) into the app,
# with the shared libraries they need and clang's resource directory, so that blitzcc works right after the two bundles are installed.
# The extension can't be a runtime dependency: Flatpak installs an app's extensions only from the remote the app came from, and the remote
# of a .flatpak bundle has none (docs/wiki/Flatpak.md).
#   /app/llvm/bin           clang and ld.lld (clang looks for ld.lld next to itself, and for its resource directory in ../lib/clang)
#   /app/llvm/lib/clang     the resource directory (headers of the compiler, compiler-rt)
#   /app/lib                libLLVM, libclang-cpp and whatever else they need from the extension; /app/lib is on the loader's path
# Usage: copy-clang.sh [<extension folder>]   (default /usr/lib/sdk/llvm21)
set -eu
sdk="${1:-/usr/lib/sdk/llvm21}"
mkdir -p /app/llvm/bin /app/llvm/lib /app/lib

# The real files, under the names that clang and blitzcc call them by.
cp -L "$sdk/bin/clang" /app/llvm/bin/clang
cp -L "$sdk/bin/ld.lld" /app/llvm/bin/ld.lld

resource="$("$sdk/bin/clang" -print-resource-dir)"
cp -a "$resource" "/app/llvm/lib/clang-resource"
mkdir -p /app/llvm/lib/clang
mv /app/llvm/lib/clang-resource "/app/llvm/lib/clang/$(basename "$resource")"

# Every library of the extension that the two load, found the way the loader finds them while the extension is mounted.
for exe in "$sdk/bin/clang" "$sdk/bin/ld.lld"; do
	ldd "$(readlink -f "$exe")" | awk '/=> \// { print $3 }'
done | sort -u | while read -r lib; do
	case "$lib" in
		"$sdk"/*) cp -L "$lib" "/app/lib/$(basename "$lib")" ;;
	esac
done

# The copy must find its own resource directory (CI checks again after a fresh install, without the extension).
test -d "$(/app/llvm/bin/clang -print-resource-dir)"
/app/llvm/bin/ld.lld --version
ls -l /app/llvm/bin /app/lib
